window.CODE = Object.assign(window.CODE || {}, {"ch39/demo/bad/CLAUDE.md":"# Clinic Helpdesk\n\nIMPORTANT: Write clean code and follow best practices.\nIMPORTANT: Always use type hints in new functions.\nIMPORTANT: Never use type hints in new functions that are quick scripts.\nCRITICAL: Be careful with patient data.\nALWAYS check the code in `code-samples/ch27/triage_v2.py` before you change anything.\n\n## Project layout\n- code-samples/: all the code\n- code-samples/ch27/: the helpdesk\n- code-samples/ch27/app.py: the web app\n- code-samples/ch27/config.py: settings\n- code-samples/ch27/helpdesk.py: the graph\n- code-samples/ch27/tools.py: the tools\n- code-samples/ch27/safety.py: safety rules\n- code-samples/ch27/knowledge.py: the search\n- code-samples/ch27/specialists.py: the specialists\n- code-samples/ch27/fake_models.py: fakes for tests\n","ch39/demo_ch39.py":"\"\"\"Show the three Chapter 39 helpers on real input. Run:  python demo_ch39.py\n\n1. lint the deliberately bad CLAUDE.md in demo/\n2. build a throwaway git repository, stage a deliberately bad change (written by hand to show the\n   checks; it is NOT output from a real coding agent), and review the diff\n3. run the helpdesk's real tests and print the evidence block\n\"\"\"\nimport subprocess\nimport sys\nimport tempfile\nfrom pathlib import Path\n\nimport diff_review\nimport evidence\nimport lint_instructions\n\nHERE = Path(__file__).resolve().parent\nREPO = HERE.parent.parent\n\n\ndef git(cwd, *a):\n    return subprocess.run([\"git\", *a], cwd=cwd, capture_output=True, text=True, check=True).stdout\n\n\nprint(\"== 1. lint_instructions on demo/bad/CLAUDE.md\")\nfor issue in lint_instructions.lint(HERE / \"demo\" / \"bad\" / \"CLAUDE.md\", REPO):\n    print(\"  \", issue)\n\nprint(\"\\n== 2. diff_review on a staged bad change\")\nwith tempfile.TemporaryDirectory() as d:\n    d = Path(d)\n    git(d, \"init\", \"-q\"); git(d, \"config\", \"user.email\", \"demo@example.com\"); git(d, \"config\", \"user.name\", \"demo\")\n    (d / \"src\").mkdir(); (d / \"tests\").mkdir()\n    (d / \"src/triage.py\").write_text('def route(msg):\\n    if \"chest pain\" in msg:\\n        return \"emergency\"\\n    return \"info\"\\n')\n    (d / \"tests/test_triage.py\").write_text('from src.triage import route\\n\\ndef test_chest_pain():\\n    assert route(\"chest pain\") == \"emergency\"\\n    assert route(\"OPD timings\") == \"info\"\\n')\n    (d / \"requirements.txt\").write_text(\"pytest\\n\")\n    git(d, \"add\", \"-A\"); git(d, \"commit\", \"-qm\", \"base\")\n    (d / \"src/triage.py\").write_text('def route(msg):\\n    try:\\n        if \"chest pain\" in msg:\\n            return \"emergency\"\\n    except Exception:\\n        pass\\n    print(\"debug\", msg)\\n    return \"info\"\\n')\n    (d / \"tests/test_triage.py\").write_text('import pytest\\nfrom src.triage import route\\n\\n@pytest.mark.skip\\ndef test_chest_pain():\\n    assert route(\"OPD timings\") == \"info\"\\n')\n    (d / \"requirements.txt\").write_text(\"pytest\\nreqeusts\\n\")\n    (d / \".github/workflows\").mkdir(parents=True); (d / \".github/workflows/ci.yml\").write_text(\"on: push\\n\")\n    git(d, \"add\", \"-A\")\n    for f in diff_review.review(git(d, \"diff\", \"--cached\"), allow=[\"src/\", \"tests/\"]):\n        print(\"  \", f)\n\nprint(\"\\n== 3. evidence from the helpdesk's real tests\")\nprint(evidence.render(evidence.run_checks([f\"{sys.executable} -m pytest -q\"], cwd=str(REPO / \"code-samples\" / \"ch27\"))))\n","ch39/diff_review.py":"\"\"\"A first-pass reviewer for a diff an AI agent produced. It finds the cheap, mechanical problems\nso that your attention goes to the part only a person can judge: is this the right change?\n\n    git diff | python diff_review.py\n    git diff main...feature | python diff_review.py --allow src/ --allow tests/\n\nIt reads a unified diff on stdin. It does NOT run the code and cannot say the change is correct.\nEvery rule is a pattern that agents are known to produce: weakening tests, silencing errors,\nadding dependencies nobody asked for, touching the guard rails themselves.\n\"\"\"\nfrom __future__ import annotations\n\nimport re\nimport sys\nfrom dataclasses import dataclass\nfrom pathlib import Path\n\nsys.path.insert(0, str(Path(__file__).resolve().parent.parent / \"ch34\"))\nfrom secret_scan import scan_text  # noqa: E402\n\nMAX_ADDED = 400\nSILENCERS = [r\"pytest\\.mark\\.skip\", r\"pytest\\.mark\\.xfail\", r\"@unittest\\.skip\", r\"\\.skip\\(\", r\"#\\s*noqa\", r\"#\\s*type:\\s*ignore\", r\"pragma:\\s*no cover\"]\nGUARD_FILES = (\".github/workflows/\", \".claude/settings\", \".claude/hooks/\", \"Dockerfile\", \".pre-commit-config\", \"CODEOWNERS\", \".mcp.json\")\nDEP_FILES = re.compile(r\"(^|/)(requirements[\\w.-]*\\.txt|pyproject\\.toml|package\\.json|Pipfile|poetry\\.lock|package-lock\\.json)$\")\n\n\n@dataclass\nclass Finding:\n    level: str          # \"block\" = do not merge without a human decision, \"warn\", \"info\"\n    file: str\n    msg: str\n\n    def __str__(self):\n        return f\"{self.level.upper():5} {self.file}: {self.msg}\"\n\n\ndef parse(diff: str) -> dict[str, dict]:\n    \"\"\"{file: {\"added\": [...], \"removed\": [...], \"new\": bool, \"deleted\": bool}}\"\"\"\n    files, cur = {}, None\n    for line in diff.splitlines():\n        if line.startswith(\"diff --git\"):\n            m = re.match(r\"diff --git a/(.*?) b/(.*)$\", line)\n            cur = files.setdefault(m.group(2), {\"added\": [], \"removed\": [], \"new\": False, \"deleted\": False})\n        elif cur is None:\n            continue\n        elif line.startswith(\"new file mode\"):\n            cur[\"new\"] = True\n        elif line.startswith(\"deleted file mode\"):\n            cur[\"deleted\"] = True\n        elif line.startswith(\"+\") and not line.startswith(\"+++\"):\n            cur[\"added\"].append(line[1:])\n        elif line.startswith(\"-\") and not line.startswith(\"---\"):\n            cur[\"removed\"].append(line[1:])\n    return files\n\n\ndef is_test(name: str) -> bool:\n    n = Path(name).name\n    return n.startswith(\"test_\") or n.endswith((\"_test.py\", \".test.ts\", \".test.js\", \".spec.ts\", \".spec.js\")) or \"/tests/\" in \"/\" + name\n\n\ndef review(diff: str, allow: list[str] | None = None) -> list[Finding]:\n    files = parse(diff)\n    out: list[Finding] = []\n    total_added = sum(len(f[\"added\"]) for f in files.values())\n    if total_added > MAX_ADDED:\n        out.append(Finding(\"warn\", \"(whole diff)\", f\"{total_added} added lines. Past ~{MAX_ADDED} nobody reviews carefully: ask the agent to split it.\"))\n    for name, f in files.items():\n        added, removed = f[\"added\"], f[\"removed\"]\n        if allow and not any(name.startswith(a) for a in allow):\n            out.append(Finding(\"warn\", name, f\"outside the allowed scope {allow}. Was it part of the task?\"))\n        if is_test(name):\n            if f[\"deleted\"]:\n                out.append(Finding(\"block\", name, \"a test file was deleted.\"))\n            rem = sum(bool(re.search(r\"\\bassert\\b|\\.assert\\w*\\(|expect\\(\", l)) for l in removed)\n            add = sum(bool(re.search(r\"\\bassert\\b|\\.assert\\w*\\(|expect\\(\", l)) for l in added)\n            if rem > add:\n                out.append(Finding(\"block\", name, f\"{rem} assertion line(s) removed, only {add} added: tests were weakened.\"))\n            rem_t = sum(bool(re.match(r\"\\s*(async )?def test_\", l)) for l in removed)\n            add_t = sum(bool(re.match(r\"\\s*(async )?def test_\", l)) for l in added)\n            if rem_t > add_t:\n                out.append(Finding(\"block\", name, f\"{rem_t - add_t} test function(s) removed.\"))\n        for pat in SILENCERS:\n            hit = [l.strip() for l in added if re.search(pat, l)]\n            if hit:\n                out.append(Finding(\"warn\", name, f\"added a way to silence a check: {hit[0][:60]}\"))\n        for i, l in enumerate(added):\n            nxt = added[i + 1].strip() if i + 1 < len(added) else \"\"\n            if re.match(r\"\\s*except(\\s+Exception)?\\s*:\\s*$\", l) and nxt in (\"pass\", \"continue\", \"return None\"):\n                out.append(Finding(\"warn\", name, \"an exception is caught and ignored (except ...: pass).\"))\n        if not is_test(name):\n            dbg = [l.strip() for l in added if re.search(r\"\\bbreakpoint\\(\\)|\\bpdb\\.set_trace|^\\s*print\\(\", l)]\n            if dbg:\n                out.append(Finding(\"info\", name, f\"debug output left in: {dbg[0][:50]}\"))\n        if DEP_FILES.search(name) and added:\n            out.append(Finding(\"warn\", name, f\"dependency file changed ({len(added)} line(s) added). Is each package real, wanted and licensed? (Chapter 43)\"))\n        if any(g in name for g in GUARD_FILES):\n            out.append(Finding(\"block\", name, \"this file controls checks, permissions or deployment. A human must read every line.\"))\n        if Path(name).name.startswith(\".env\") and not name.endswith(\".example\"):\n            out.append(Finding(\"block\", name, \"an .env file is in the diff; it holds secrets.\"))\n        for rule, shown in scan_text(\"\\n\".join(added)):\n            out.append(Finding(\"block\", name, f\"looks like a secret: {rule} {shown}\"))\n        todo = [l.strip() for l in added if re.search(r\"\\b(TODO|FIXME|XXX)\\b\", l)]\n        if todo:\n            out.append(Finding(\"info\", name, f\"left a marker: {todo[0][:50]}\"))\n    order = {\"block\": 0, \"warn\": 1, \"info\": 2}\n    return sorted(out, key=lambda x: (order[x.level], x.file))\n\n\nif __name__ == \"__main__\":\n    args = sys.argv[1:]\n    allow = [args[i + 1] for i, a in enumerate(args) if a == \"--allow\"]\n    findings = review(sys.stdin.read(), allow or None)\n    print(\"\\n\".join(map(str, findings)) if findings else \"No mechanical problems found. (That is not the same as correct.)\")\n    sys.exit(2 if any(f.level == \"block\" for f in findings) else 0)\n","ch39/evidence.py":"\"\"\"Run the checks yourself and keep the evidence, instead of trusting 'all tests pass'.\n\nAn agent's summary is a claim. A command's exit code and output are evidence. This runs a list of\ncommands (no shell, so nothing is expanded behind your back), times each one, and prints a block you\ncan paste into a pull request or a handoff note (Chapter 42).\n\n    python evidence.py \"python -m pytest -q\" \"python -m ruff check .\"\n\"\"\"\nfrom __future__ import annotations\n\nimport shlex\nimport subprocess\nimport sys\nimport time\nfrom dataclasses import dataclass\n\n\n@dataclass\nclass Result:\n    command: str\n    code: int\n    seconds: float\n    tail: str\n\n    @property\n    def ok(self):\n        return self.code == 0\n\n\ndef run_checks(commands: list[str], cwd: str = \".\", timeout: int = 300, tail_lines: int = 6) -> list[Result]:\n    results = []\n    for cmd in commands:\n        start = time.time()\n        try:\n            p = subprocess.run(shlex.split(cmd), cwd=cwd, capture_output=True, text=True, timeout=timeout)\n            code, text = p.returncode, (p.stdout + p.stderr)\n        except subprocess.TimeoutExpired:\n            code, text = 124, f\"timed out after {timeout}s\"\n        except FileNotFoundError as e:\n            code, text = 127, f\"command not found: {e.filename}\"\n        tail = \"\\n\".join(text.strip().splitlines()[-tail_lines:])\n        results.append(Result(cmd, code, round(time.time() - start, 1), tail))\n    return results\n\n\ndef render(results: list[Result]) -> str:\n    out = []\n    for r in results:\n        out.append(f\"$ {r.command}\\n[{'PASS' if r.ok else 'FAIL'} exit={r.code} {r.seconds}s]\\n{r.tail}\\n\")\n    out.append(\"ALL CHECKS PASSED\" if all(r.ok for r in results) else \"AT LEAST ONE CHECK FAILED\")\n    return \"\\n\".join(out)\n\n\nif __name__ == \"__main__\":\n    res = run_checks(sys.argv[1:])\n    print(render(res))\n    sys.exit(0 if all(r.ok for r in res) else 1)\n","ch39/lint_instructions.py":"\"\"\"Check an instruction file (CLAUDE.md, AGENTS.md, a rules file) for the problems that make agents ignore it.\n\n    python lint_instructions.py starter/AGENTS.md\n    python lint_instructions.py starter/CLAUDE.md --root starter\n\nEach check comes from advice on the vendors' pages (read 5 Nov 2026): keep it short, put the exact\ncommands in, say only what the code cannot tell the agent, avoid contradictions, point only at\nfiles that exist. A linter cannot tell whether your rules are GOOD; it finds the cheap mistakes.\n\"\"\"\nfrom __future__ import annotations\n\nimport re\nimport sys\nfrom dataclasses import dataclass\nfrom pathlib import Path\n\nsys.path.insert(0, str(Path(__file__).resolve().parent.parent / \"ch34\"))\nfrom secret_scan import scan_text  # noqa: E402  (the Chapter 34 scanner: instruction files must never hold secrets)\n\nMAX_LINES = 200            # \"target under 200 lines per CLAUDE.md file\" (Claude Code memory page)\nMAIN_FILES = {\"CLAUDE.md\", \"AGENTS.md\", \"CLAUDE.local.md\", \"copilot-instructions.md\"}   # the files that should carry the commands\nMAX_IMPORT_DEPTH = 4       # imports can chain up to four hops (same page)\nVAGUE = [\"write clean code\", \"follow best practices\", \"be careful\", \"high quality\", \"good code\",\n         \"make sure it works\", \"be thorough\", \"don't make mistakes\", \"think hard\"]\nPOS = (\"always\", \"must\", \"should\", \"prefer\", \"use\")\nNEG = (\"never\", \"do not\", \"don't\", \"must not\", \"avoid\")\nSTOP = set(\"a an the to in of for and or is are be it that this with as on at by from you your when\".split())\n\n\n@dataclass\nclass Issue:\n    level: str      # \"warn\" or \"info\"\n    line: int       # 0 = whole file\n    rule: str\n    msg: str\n\n    def __str__(self):\n        where = f\"line {self.line}\" if self.line else \"file\"\n        return f\"{self.level.upper():4} {where:8} [{self.rule}] {self.msg}\"\n\n\ndef _words(s: str) -> frozenset:\n    return frozenset(w for w in re.findall(r\"[a-z0-9_.]+\", s.lower()) if w not in STOP)\n\n\ndef _polarity(line: str):\n    low = line.lower().lstrip(\"-*0123456789. \").strip()\n    for n in NEG:                      # check negative forms first: \"do not use X\" also contains \"use\"\n        if low.startswith(n) or f\" {n} \" in f\" {low} \":\n            return \"neg\", _words(re.sub(rf\"\\b{re.escape(n)}\\b\", \"\", low, count=1))\n    for p in POS:\n        if low.startswith(p) or f\" {p} \" in f\" {low} \":\n            return \"pos\", _words(re.sub(rf\"\\b{re.escape(p)}\\b\", \"\", low, count=1))\n    return None, frozenset()\n\n\ndef _import_depth(path: Path, root: Path, seen=()) -> int:\n    if path in seen or not path.is_file():\n        return 0\n    deepest = 0\n    for imp in re.findall(r\"^\\s*@(\\S+)\", path.read_text(errors=\"replace\"), re.M):\n        target = (path.parent / imp).resolve()\n        deepest = max(deepest, 1 + _import_depth(target, root, seen + (path,)))\n    return deepest\n\n\ndef _expanded(path: Path, depth: int = 0) -> str:\n    \"\"\"The file's text plus the text of everything it imports (what the agent actually reads).\"\"\"\n    text = path.read_text(errors=\"replace\")\n    if depth < MAX_IMPORT_DEPTH:\n        for imp in re.findall(r\"^\\s*@(\\S+)\", text, re.M):\n            if (path.parent / imp).is_file():\n                text += \"\\n\" + _expanded(path.parent / imp, depth + 1)\n    return text\n\n\ndef lint(path: str | Path, root: str | Path | None = None) -> list[Issue]:\n    path = Path(path)\n    root = Path(root) if root else path.parent\n    text = path.read_text(errors=\"replace\")\n    lines = text.splitlines()\n    out: list[Issue] = []\n\n    if len(lines) > MAX_LINES:\n        out.append(Issue(\"warn\", 0, \"too-long\", f\"{len(lines)} lines. Every line is read on every task; past ~{MAX_LINES} the important ones get lost.\"))\n\n    has_command = any(re.search(r\"`[a-z][^`]*\\s[^`]*`\", l) and re.search(r\"test|pytest|npm|pnpm|make|lint|build|run|tsc\", l, re.I) for l in _expanded(path).splitlines())\n    if not has_command and path.name in MAIN_FILES:\n        out.append(Issue(\"warn\", 0, \"no-commands\", \"No command for running tests or checks. That one line lets the agent verify its own work.\"))\n\n    shouty = [i for i, l in enumerate(lines, 1) if re.search(r\"\\b(IMPORTANT|CRITICAL|MUST|NEVER|ALWAYS)\\b\", l)]\n    if len(shouty) > 3:\n        out.append(Issue(\"info\", shouty[0], \"emphasis\", f\"{len(shouty)} lines shout. Current models follow plain wording; a rule that truly cannot bend belongs in a hook or deny rule (Chapter 41).\"))\n\n    for i, l in enumerate(lines, 1):\n        low = l.lower()\n        for v in VAGUE:\n            if v in low:\n                out.append(Issue(\"info\", i, \"vague\", f\"'{v}' gives the agent nothing to act on. Say what to do in this repository.\"))\n\n    tree_like = [i for i, l in enumerate(lines, 1) if re.match(r\"^\\s*[-*]\\s*`?[\\w./-]*[/.][\\w./-]*`?\\s*(:|-|–|—)\\s\", l)]\n    if len(tree_like) > 8:\n        out.append(Issue(\"info\", tree_like[0], \"derivable\", f\"{len(tree_like)} lines describe the folder layout. The agent reads the repository itself; keep only what the code does not show.\"))\n\n    for i, l in enumerate(lines, 1):\n        for token in re.findall(r\"`([^`\\s]+)`\", l):\n            if re.fullmatch(r\"[\\w./-]+\\.(py|md|json|ya?ml|toml|txt|js|ts)\", token) and \"*\" not in token:\n                if not any((base / token).exists() for base in (root, path.parent)):\n                    out.append(Issue(\"warn\", i, \"missing-file\", f\"`{token}` is not in the repository.\"))\n\n    for i, l in enumerate(lines, 1):\n        m = re.match(r\"^\\s*@(\\S+)\", l)\n        if m and not (path.parent / m.group(1)).is_file():\n            out.append(Issue(\"warn\", i, \"missing-import\", f\"@{m.group(1)} does not exist.\"))\n    if _import_depth(path.resolve(), root.resolve()) > MAX_IMPORT_DEPTH:\n        out.append(Issue(\"warn\", 0, \"import-depth\", f\"Imports chain deeper than {MAX_IMPORT_DEPTH} hops; the extra ones are not followed.\"))\n\n    pols = [(i, *_polarity(l)) for i, l in enumerate(lines, 1) if l.strip().startswith((\"-\", \"*\", \"1\", \"2\", \"3\")) or l[:1].isalpha()]\n    for a in range(len(pols)):\n        for b in range(a + 1, len(pols)):\n            (i, p1, w1), (j, p2, w2) = pols[a], pols[b]\n            if p1 and p2 and p1 != p2 and len(w1 & w2) >= 3 and len(w1 & w2) / min(len(w1), len(w2)) >= 0.8:\n                out.append(Issue(\"warn\", j, \"contradiction\", f\"Line {j} may contradict line {i}. When two rules disagree the agent may pick either.\"))\n\n    for rule, shown in scan_text(text):\n        out.append(Issue(\"warn\", 0, \"secret\", f\"Looks like a {rule} ({shown}). Instruction files are committed and sent to the model.\"))\n    return out\n\n\nif __name__ == \"__main__\":\n    args = sys.argv[1:]\n    root = args[args.index(\"--root\") + 1] if \"--root\" in args else None\n    files = [a for i, a in enumerate(args) if not a.startswith(\"--\") and (i == 0 or args[i - 1] != \"--root\")]\n    bad = 0\n    for f in files:\n        issues = lint(f, root)\n        print(f\"{f}: {len(issues)} issue(s)\" if issues else f\"{f}: clean\")\n        for it in issues:\n            print(\"  \", it)\n        bad += sum(i.level == \"warn\" for i in issues)\n    sys.exit(1 if bad else 0)\n","ch39/README.md":"# Chapter 39 · Working well with a coding agent\n\n| file | what it is |\n| --- | --- |\n| `starter/` | real instruction files for the Clinic Helpdesk: `AGENTS.md`, `CLAUDE.md` (imports it), `.claude/rules/tests.md` |\n| `lint_instructions.py` | finds cheap mistakes in instruction files (too long, no commands, contradictions, missing files, secrets) |\n| `diff_review.py` | first-pass review of an AI-written diff: weakened tests, silenced checks, new dependencies, guard-rail files |\n| `evidence.py` | runs your checks and prints exit codes and output you can paste into a pull request |\n| `demo/bad/CLAUDE.md` | a deliberately bad file that triggers every lint rule |\n| `demo_ch39.py` | runs all three tools on real input |\n\n    python -m pytest -q           # 16 tests; needs git\n    python demo_ch39.py\n    python lint_instructions.py starter/AGENTS.md --root ../..\n\nThe staged \"bad change\" in the demo was written by hand to exercise the checks. It is not output from a real coding agent.\n","ch39/starter/.claude/rules/tests.md":"---\npaths:\n  - \"code-samples/ch27/test_*.py\"\n---\n\n- Tests use the stand-in model from `code-samples/ch27/fake_models.py`. A test must not need an API key.\n- One behaviour per test. Name it for the behaviour: `test_emergency_message_never_reaches_a_model`.\n- Never delete or loosen an assertion to make a test pass. Fix the code, or ask.\n","ch39/starter/AGENTS.md":"# Clinic Helpdesk (City Clinic, synthetic data only)\n\n## Commands\n- Run all tests: `cd code-samples/ch27 && python -m pytest -q`\n- Run one test: `cd code-samples/ch27 && python -m pytest -q test_helpdesk.py -k emergency`\n- Score the whole helpdesk (offline stand-in model): `cd code-samples/ch27 && python eval_helpdesk.py`\n- Tests and eval run offline with the stand-in model. Add `LIVE=1` (tests) or `--live` (eval) only when asked.\n\n## Rules that are easy to get wrong\n- The tools in `code-samples/ch27/tools.py` are read-only. Booking is graph code that runs only after a person approves (`code-samples/ch27/helpdesk.py`). Do not add a booking tool.\n- Emergency messages are answered by `code-samples/ch27/safety.py` before any model runs. Do not route them through a specialist.\n- All limits live in `code-samples/ch27/config.py`. Do not hard-code a number such as a step limit elsewhere.\n- Every reply is at most `MAX_REPLY_WORDS` words and may only state facts that came from a tool or a policy document.\n- Patient data in tests is made up. Never paste a real name, phone number or UHID into code, tests or prompts.\n\n## Done means\n- The test command above passes, and you show its output.\n- A new behaviour has a new test that failed before your change.\n","ch39/starter/CLAUDE.md":"@AGENTS.md\n\n# Claude Code only\n- Work in plan mode first for anything that touches more than two files.\n- Use a subagent to read `docs/` or long test logs, so the output stays out of this conversation.\n\n# Compact instructions\nWhen compacting, keep the list of changed files, the failing test names and the exact commands that were run.\n","ch39/test_ch39.py":"import subprocess\nimport sys\nfrom pathlib import Path\n\nimport diff_review as dr\nimport evidence as ev\nimport lint_instructions as li\n\nHERE = Path(__file__).resolve().parent\nREPO = HERE.parent.parent          # the course repository root\n\n\ndef write(tmp_path, name, text):\n    p = tmp_path / name\n    p.parent.mkdir(parents=True, exist_ok=True)\n    p.write_text(text)\n    return p\n\n\n# ---------- instruction-file linter ----------\ndef test_starter_files_are_clean():\n    for f in (\"AGENTS.md\", \"CLAUDE.md\", \".claude/rules/tests.md\"):\n        assert li.lint(HERE / \"starter\" / f, REPO) == [], f\n\n\ndef test_long_file_and_no_commands(tmp_path):\n    p = write(tmp_path, \"CLAUDE.md\", \"# Notes\\n\" + \"Some prose line.\\n\" * 250)\n    rules = {i.rule for i in li.lint(p)}\n    assert {\"too-long\", \"no-commands\"} <= rules\n\n\ndef test_missing_file_and_import(tmp_path):\n    p = write(tmp_path, \"AGENTS.md\", \"@nope.md\\n- Test: `pytest -q`\\n- See `src/gone.py`\\n\")\n    rules = [i.rule for i in li.lint(p)]\n    assert \"missing-import\" in rules and \"missing-file\" in rules\n\n\ndef test_contradiction_found(tmp_path):\n    p = write(tmp_path, \"AGENTS.md\", \"- Test: `pytest -q`\\n- Always use type hints in new functions\\n- Never use type hints in new functions\\n\")\n    assert any(i.rule == \"contradiction\" for i in li.lint(p))\n\n\ndef test_unrelated_rules_do_not_contradict(tmp_path):\n    p = write(tmp_path, \"AGENTS.md\", \"- Test: `pytest -q`\\n- Always use type hints in new functions\\n- Never commit directly to main\\n\")\n    assert not any(i.rule == \"contradiction\" for i in li.lint(p))\n\n\ndef test_vague_emphasis_and_secret(tmp_path):\n    body = \"- Test: `pytest -q`\\n- Write clean code\\n\" + \"- IMPORTANT keep it short\\n\" * 4 + \"- key sk-ant-\" + \"a\" * 30 + \"\\n\"\n    rules = {i.rule for i in li.lint(write(tmp_path, \"AGENTS.md\", body))}\n    assert {\"vague\", \"emphasis\", \"secret\"} <= rules\n\n\ndef test_import_depth(tmp_path):\n    for n in range(6):\n        write(tmp_path, f\"f{n}.md\", f\"@f{n + 1}.md\\n\" if n < 5 else \"end\\n\")\n    write(tmp_path, \"CLAUDE.md\", \"@f0.md\\n- Test: `pytest -q`\\n\")\n    assert any(i.rule == \"import-depth\" for i in li.lint(tmp_path / \"CLAUDE.md\"))\n\n\ndef test_cli_exit_code(tmp_path):\n    bad = write(tmp_path, \"AGENTS.md\", \"Write clean code\\n\")\n    r = subprocess.run([sys.executable, str(HERE / \"lint_instructions.py\"), str(bad)], capture_output=True, text=True)\n    assert r.returncode == 1 and \"no-commands\" in r.stdout\n\n\n# ---------- diff reviewer (diffs made by real git) ----------\ndef git(cwd, *args):\n    return subprocess.run([\"git\", *args], cwd=cwd, capture_output=True, text=True, check=True).stdout\n\n\ndef repo_with_change(tmp_path, before: dict, after: dict):\n    git(tmp_path, \"init\", \"-q\")\n    git(tmp_path, \"config\", \"user.email\", \"t@example.com\")\n    git(tmp_path, \"config\", \"user.name\", \"t\")\n    for n, t in before.items():\n        write(tmp_path, n, t)\n    git(tmp_path, \"add\", \"-A\")\n    git(tmp_path, \"commit\", \"-qm\", \"base\")\n    for n, t in after.items():\n        if t is None:\n            (tmp_path / n).unlink()\n        else:\n            write(tmp_path, n, t)\n    git(tmp_path, \"add\", \"-A\")\n    return git(tmp_path, \"diff\", \"--cached\")\n\n\ndef test_weakened_test_is_blocked(tmp_path):\n    d = repo_with_change(tmp_path,\n                         {\"test_a.py\": \"def test_x():\\n    assert f(1) == 2\\n    assert f(2) == 3\\n\"},\n                         {\"test_a.py\": \"def test_x():\\n    assert f(1) == 2\\n\"})\n    f = dr.review(d)\n    assert f[0].level == \"block\" and \"weakened\" in f[0].msg\n\n\ndef test_deleted_test_file_and_skip(tmp_path):\n    d = repo_with_change(tmp_path, {\"test_a.py\": \"def test_x():\\n    assert 1\\n\", \"test_b.py\": \"def test_y():\\n    assert 1\\n\"},\n                         {\"test_a.py\": None, \"test_b.py\": \"import pytest\\n@pytest.mark.skip\\ndef test_y():\\n    assert 1\\n\"})\n    msgs = [str(x) for x in dr.review(d)]\n    assert any(\"test file was deleted\" in m for m in msgs)\n    assert any(\"silence a check\" in m for m in msgs)\n\n\ndef test_scope_dependency_secret_guard_and_swallowed_error(tmp_path):\n    d = repo_with_change(tmp_path, {\"src/a.py\": \"x = 1\\n\", \"requirements.txt\": \"pytest\\n\"},\n                         {\"src/a.py\": \"try:\\n    x = 1\\nexcept Exception:\\n    pass\\nprint('debug')\\n\",\n                          \"requirements.txt\": \"pytest\\nreqeusts\\n\",\n                          \"other/b.py\": \"k = 'sk-ant-\" + \"b\" * 30 + \"'\\n\",\n                          \".github/workflows/ci.yml\": \"on: push\\n\"})\n    text = \"\\n\".join(map(str, dr.review(d, allow=[\"src/\", \"requirements\"])))\n    for needle in (\"outside the allowed scope\", \"except ...: pass\", \"dependency file changed\", \"looks like a secret\", \"controls checks\", \"debug output\"):\n        assert needle in text, needle\n\n\ndef test_big_diff_warns_and_clean_diff_passes(tmp_path):\n    d = repo_with_change(tmp_path, {\"a.py\": \"x = 1\\n\"}, {\"a.py\": \"x = 1\\n\" + \"y = 2\\n\" * 450})\n    assert any(\"added lines\" in f.msg for f in dr.review(d))\n    sub = tmp_path / \"second\"\n    sub.mkdir()\n    d2 = repo_with_change(sub, {\"a.py\": \"x = 1\\n\"}, {\"a.py\": \"x = 2\\n\"})\n    assert dr.review(d2) == []\n\n\ndef test_cli_exit_code_2_on_block(tmp_path):\n    d = repo_with_change(tmp_path, {\".env\": \"A=1\\n\"}, {\".env\": \"A=2\\n\"})\n    r = subprocess.run([sys.executable, str(HERE / \"diff_review.py\")], input=d, capture_output=True, text=True)\n    assert r.returncode == 2 and \"BLOCK\" in r.stdout\n\n\n# ---------- evidence ----------\ndef test_evidence_pass_fail_timeout_missing():\n    res = ev.run_checks([f\"{sys.executable} -c \\\"print('ok')\\\"\", f\"{sys.executable} -c \\\"import sys; sys.exit(3)\\\"\",\n                         f\"{sys.executable} -c \\\"import time; time.sleep(5)\\\"\", \"no-such-command-xyz\"], timeout=1)\n    assert [r.code for r in res] == [0, 3, 124, 127]\n    text = ev.render(res)\n    assert \"[PASS exit=0\" in text and \"[FAIL exit=3\" in text and \"timed out\" in text and \"AT LEAST ONE CHECK FAILED\" in text\n\n\ndef test_evidence_on_the_real_helpdesk_tests():\n    res = ev.run_checks([f\"{sys.executable} -m pytest -q\"], cwd=str(REPO / \"code-samples\" / \"ch27\"))\n    assert res[0].ok and \"passed\" in res[0].tail\n\n\ndef test_bad_demo_file_triggers_every_rule():\n    rules = {i.rule for i in li.lint(HERE / \"demo\" / \"bad\" / \"CLAUDE.md\", REPO)}\n    assert {\"no-commands\", \"emphasis\", \"vague\", \"derivable\", \"missing-file\", \"contradiction\"} <= rules\n","common/requirements.txt":"# Pinned versions the course code was tested with. Install with: pip install -r requirements.txt\nopenai==3.43.0\nanthropic==2.4.0\npython-dotenv>=1.0\npydantic==2.13.5\ntiktoken>=0.8            # Chapter 2\nfastapi==0.162.0         # Chapter 5\nuvicorn>=0.30\npython-multipart>=0.0.9\nhttpx>=0.27\nstreamlit==1.66.1\ngradio==6.31.0\npytest>=8\n\n# Part C: frameworks and protocols (tested versions)\nlangchain==1.4.8                 # Chapters 12-13\nlangchain-core==1.7.4\nlangchain-openai==1.7.3\nlangchain-anthropic==1.7.9\nlangchain-community==0.4.2\nlangchain-text-splitters==1.1.3\nlangchain-classic==1.0.8         # only for legacy examples (AgentExecutor, old retrievers)\nlanggraph==1.2.19                # Chapters 14-15\nlanggraph-checkpoint-sqlite==3.1.3\nmcp==1.30.0                      # Chapters 16-17\nlangchain-mcp-adapters==0.3.2\nnetworkx==3.7                    # Chapter 18 (GraphRAG)\nchromadb==1.5.9                  # Chapters 6, 18, 19\nagno==3.1.12                     # Chapter 19\n# Optional: langchain-tavily, wikipedia, langchain-experimental (Chapter 13 built-in tools)\n# DSPy (Chapter 20) goes in a separate environment: see ch20/requirements-dspy.txt\n\n# Part D: multi-agent\n# CrewAI (Chapter 24) and AutoGen (Chapter 25) need their own environments: ch24/requirements-crewai.txt, ch25/requirements-autogen.txt\na2a-sdk==1.3.0                   # Chapter 26 (agent interoperability)\nfastapi==0.162.0\nuvicorn==0.54.0\n"});
